  PRIMARY KEY (`position_id`) USING BTREE,
  INDEX `_dta_index_Base_Position_8_478429274__K3_K4_K1_24`(`position_name` ASC, `storage_id` ASC, `position_id` ASC) USING BTREE,
  INDEX `_dta_index_Base_Position_8_8337`(`position_name` ASC, `storage_id` ASC, `position_type` ASC, `is_locked` ASC, `is_freeze` ASC, `area_code` ASC, `shelve_code` ASC, `column_code` ASC, `row_code` ASC, `max_capacity` ASC) USING BTREE,
  INDEX `_dta_index_Base_Position_8__24`(`position_type` ASC, `storage_id` ASC, `position_name` ASC, `position_id` ASC) USING BTREE,
  INDEX `_dta_index_Base_Position_8_1231916056__K4_K2`(`storage_id` ASC, `parent_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 73757 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '货位管理' ROW_FORMAT = Dynamic;

