  `remark` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '备注',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人id',
  `create_by_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint NULL DEFAULT NULL COMMENT '修改人id',
  `update_by_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `del_flag` tinyint(1) NULL DEFAULT 0 COMMENT '删除标志',
  `delete_time` datetime NULL DEFAULT NULL COMMENT '删除时间',
  `delete_by` bigint NULL DEFAULT NULL COMMENT '删除人id',
  `delete_by_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '删除人',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户编号',
  `net_weight` decimal(14, 4) NULL DEFAULT NULL COMMENT '单位净重',
  `row_net_weight` decimal(14, 4) NULL DEFAULT NULL COMMENT '小计净重',
  `row_net_weight_origin` decimal(14, 4) NULL DEFAULT NULL COMMENT '原始净重',
  `row_weight_ton` decimal(18, 5) NULL DEFAULT NULL COMMENT '合计重量(吨)',
