  `row_cube` decimal(14, 4) NULL DEFAULT NULL COMMENT '小计体积',
  `big_qty` decimal(14, 4) NULL DEFAULT NULL COMMENT '大单位数量',
  `images` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '图片',
  `thermoc_line` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '温层',
