  `case_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '箱号',
  `parcel_quantity` decimal(10, 6) NULL DEFAULT NULL COMMENT '包数',
  `parcel_average_weight` decimal(10, 4) NULL DEFAULT NULL COMMENT '均重',
  PRIMARY KEY (`inventory_id`) USING BTREE,
  INDEX `index_positionName_storage_Id`(`position_name` ASC, `storage_id` ASC) USING BTREE,
  INDEX `index_product_Id`(`product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 63204 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '库存明细' ROW_FORMAT = Dynamic;

