  `shelf_life_date` datetime NULL DEFAULT NULL COMMENT '库存保质期',
  `valid_shelf_life_day` int NULL DEFAULT NULL COMMENT '最长库存天数',
  `limit_date` date NULL DEFAULT NULL COMMENT '有效期至',
  `produce_date` datetime NULL DEFAULT NULL COMMENT '生成日期',
  `weight` decimal(14, 4) NULL DEFAULT NULL COMMENT '单位重量',
  `other_in_weight` decimal(14, 4) NULL DEFAULT NULL COMMENT '其他入库数量',
  `borrow_in_weight` decimal(14, 4) NULL DEFAULT NULL COMMENT '借入入库数量',
  `return_weight` decimal(14, 4) NULL DEFAULT NULL COMMENT '退货入库数量',
  `check_in_weight` decimal(14, 4) NULL DEFAULT NULL COMMENT '盘盈入库数量',
  `borrow_out_weight` decimal(14, 4) NULL DEFAULT NULL COMMENT '借出出库数量',
  `other_out_weight` decimal(14, 4) NULL DEFAULT NULL COMMENT '其他出库数量',
  `check_out_weight` decimal(14, 4) NULL DEFAULT NULL COMMENT '盘亏出库数量',
  `net_weight` decimal(32, 4) NULL DEFAULT NULL COMMENT '净重（克）',
  `row_net_weight` decimal(32, 4) NULL DEFAULT NULL COMMENT '净重重量KG',
  `row_net_weight_origin` decimal(32, 4) NULL DEFAULT NULL COMMENT '原始重量',
  `row_net_weight_ton` decimal(32, 4) NULL DEFAULT NULL COMMENT '重量吨',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人id',
