  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户编号',
  `holder_storage` decimal(32, 4) NULL DEFAULT 0.0000 COMMENT '占位量',
  PRIMARY KEY (`storage_day_id`) USING BTREE,
  INDEX `_dta_index_Stat_StorageDay_36`(`storage_day` ASC, `storage_id` ASC, `consignor_id` ASC, `product_id` ASC, `storage_name` ASC, `consignor_code` ASC, `consignor_name` ASC, `product_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '每日库存快照' ROW_FORMAT = Dynamic;

