  `phone_verified` tinyint NULL DEFAULT NULL COMMENT '手机号已验证',
  `email_verified` tinyint NULL DEFAULT NULL COMMENT 'email已验证',
  `license_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '统一社会信用代码',
  `linker` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系人',
  `fax` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '传真',
  `province_id` int NULL DEFAULT NULL COMMENT '省id',
