-- ----------------------------
-- Function structure for camelToUnderline
-- ----------------------------
DROP FUNCTION IF EXISTS `camelToUnderline`;
delimiter ;;
CREATE FUNCTION `camelToUnderline`(paramString VARCHAR(200))
 RETURNS varchar(200) CHARSET utf8mb3
  DETERMINISTIC
begin
set paramString = replace(paramString, 'A', '_a');
set paramString = replace(paramString, 'B', '_b');
set paramString = replace(paramString, 'C', '_c');
set paramString = replace(paramString, 'D', '_d');
set paramString = replace(paramString, 'E', '_e');
set paramString = replace(paramString, 'F', '_f');
set paramString = replace(paramString, 'G', '_g');
set paramString = replace(paramString, 'H', '_h');
set paramString = replace(paramString, 'I', '_i');
set paramString = replace(paramString, 'J', '_j');
set paramString = replace(paramString, 'K', '_k');
set paramString = replace(paramString, 'L', '_l');
set paramString = replace(paramString, 'M', '_m');
set paramString = replace(paramString, 'N', '_n');
set paramString = replace(paramString, 'O', '_o');
set paramString = replace(paramString, 'P', '_p');
set paramString = replace(paramString, 'Q', '_q');
set paramString = replace(paramString, 'R', '_r');
set paramString = replace(paramString, 'S', '_s');
set paramString = replace(paramString, 'T', '_t');
set paramString = replace(paramString, 'U', '_u');
set paramString = replace(paramString, 'V', '_v');
set paramString = replace(paramString, 'W', '_w');
set paramString = replace(paramString, 'X', '_x');
set paramString = replace(paramString, 'Y', '_y');
set paramString = replace(paramString, 'Z', 'z');
set paramString = replace(paramString, '__', '_');
RETURN paramString;
end
;;
delimiter ;

-- ----------------------------
-- Function structure for firstToLower
-- ----------------------------
DROP FUNCTION IF EXISTS `firstToLower`;
delimiter ;;
CREATE FUNCTION `firstToLower`(`value` VARCHAR(200))
 RETURNS varchar(200) CHARSET utf8mb3
  DETERMINISTIC
BEGIN
	#Routine body goes here...

	RETURN CONCAT(LOWER(LEFT(`value`,1)),SUBSTRING(`value`,2,(LENGTH(`value`)-1)));
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
