INSERT INTO `magic_api_file` VALUES ('/dev-api/api/应用管理/业务员管理/group.json', '{\n  \"properties\" : { },\n  \"id\" : \"ff373d34da3d4acb91d825c870a15b4d\",\n  \"name\" : \"业务员管理\",\n  \"type\" : \"api\",\n  \"parentId\" : \"fc09d5b985f44120956d5d4f9fbd3658\",\n  \"path\" : \"sales\",\n  \"createTime\" : null,\n  \"updateTime\" : 1740359843946,\n  \"createBy\" : null,\n  \"updateBy\" : null,\n  \"paths\" : [ ],\n  \"options\" : [ ]\n}', NULL, NULL, NULL, NULL, '2025-02-24 09:16:41', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/应用管理/业务员管理/列表.ms', '{\n  \"properties\" : { },\n  \"id\" : \"4869b8044f8a4b3eb414b2e7e944bc36\",\n  \"script\" : null,\n  \"groupId\" : \"ff373d34da3d4acb91d825c870a15b4d\",\n  \"name\" : \"列表\",\n  \"createTime\" : null,\n  \"updateTime\" : 1740367004734,\n  \"lock\" : null,\n  \"createBy\" : null,\n  \"updateBy\" : null,\n  \"path\" : \"list\",\n  \"method\" : \"POST\",\n  \"parameters\" : [ ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : null,\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport cn.dev33.satoken.stp.StpUtil;\r\nimport magic.boot.utils.LoginHelper;\r\n\r\nlet loginUser = LoginHelper.getLoginUser();\r\nlet userId = LoginHelper.getUserId();\r\nlet isAdmin = loginUser.isAdministrator();\r\n\r\nlet result = db.page(\"\"\"\r\n    select * from base_salesman \r\n    where 1=1\r\n    ?{!isAdmin, and create_by = #{userId}}\r\n    ?{body.salesCode, and sales_code like concat(\'%\',#{body.salesCode},\'%\')}\r\n    ?{body.salesType , and sales_type like concat(\'%\',#{body.salesType},\'%\')}\r\n    order by sales_id desc\r\n\"\"\");\r\n\r\nif(!result.rows){\r\n    result.rows=[];\r\n}\r\nreturn result ;', NULL, NULL, NULL, NULL, '2025-02-24 11:10:45', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/应用管理/业务员管理/删除.ms', '{\n  \"properties\" : { },\n  \"id\" : \"579ad0f9fc144283982c712ea4313426\",\n  \"script\" : null,\n  \"groupId\" : \"ff373d34da3d4acb91d825c870a15b4d\",\n  \"name\" : \"删除\",\n  \"createTime\" : null,\n  \"updateTime\" : 1740367020775,\n  \"lock\" : null,\n  \"createBy\" : null,\n  \"updateBy\" : null,\n  \"path\" : \"delete/{id}\",\n  \"method\" : \"DELETE\",\n  \"parameters\" : [ ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : null,\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nvar val = db.transaction(()=>{\r\n    db.table(\"base_salesman\").where().in(\"sales_id\", id.split(\",\")).delete()\r\n    return \"OK\"\r\n});\r\n\r\nreturn {\r\n    msg: val\r\n};', NULL, NULL, NULL, NULL, '2025-02-24 11:11:09', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/应用管理/业务员管理/编辑保存.ms', '{\n  \"properties\" : { },\n  \"id\" : \"4126d5ace7984afd8e6ee3183f8b9ed0\",\n  \"script\" : null,\n  \"groupId\" : \"ff373d34da3d4acb91d825c870a15b4d\",\n  \"name\" : \"编辑保存\",\n  \"createTime\" : null,\n  \"updateTime\" : 1740366877108,\n  \"lock\" : null,\n  \"createBy\" : null,\n  \"updateBy\" : null,\n  \"path\" : \"saveEditor\",\n  \"method\" : \"POST\",\n  \"parameters\" : [ ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : null,\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport cn.hutool.json.JSONUtil;\r\nimport cn.hutool.core.util.ObjectUtil;\r\nimport http;\r\nimport request;\r\n\r\n\r\nvar mainInfo = {};\r\n//排除掉 body 对象中的 明细集合\r\nvar entries = JSONUtil.parseObj(body);\r\nentries.forEach((key, value) => {\r\n    if(key!=\"detailTable\"){\r\n        mainInfo[key] = value;\r\n    }\r\n});\r\nif(!body.projectId){\r\n    mainInfo.projectId = undefined;\r\n}\r\nif(!body.projectCode){\r\n    //获取编码\r\n    var authorization=request.getHeaders(\'Authorization\')[0]; \r\n    var clientid=request.getHeaders(\'Clientid\')[0]; \r\n    var url =\"http://172.18.0.10:7852/system/core/common/getCodeRegular/5001\";\r\n    var result=http.connect(url).header({\r\n        \"Authorization\":authorization,\r\n        \"Clientid\":clientid,\r\n    }).post().getBody();\r\n    mainInfo.projectCode= result.data.code;\r\n\r\n}\r\n// 主表新增喝保存通用\r\ndb.table(\'base_salesman\').primary(\'sales_id\').save(mainInfo);\r\n//查询出Id\r\nlet mainData = db.selectOne(\'select * from base_salesman ORDER BY sales_id DESC limit 1\');\r\nmainInfo.projectId = mainData.projectId;\r\n\r\nlet detailTable = []; \r\nmainData.detailTable = detailTable;\r\nreturn mainData;', NULL, NULL, NULL, NULL, '2025-02-24 11:08:08', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/应用管理/业务员管理/编辑查询.ms', '{\n  \"properties\" : { },\n  \"id\" : \"e0d118f3eddd4f678695592599590845\",\n  \"script\" : null,\n  \"groupId\" : \"ff373d34da3d4acb91d825c870a15b4d\",\n  \"name\" : \"编辑查询\",\n  \"createTime\" : null,\n  \"updateTime\" : 1740366920302,\n  \"lock\" : null,\n  \"createBy\" : null,\n  \"updateBy\" : null,\n  \"path\" : \"editor\",\n  \"method\" : \"POST\",\n  \"parameters\" : [ ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : null,\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport cn.dev33.satoken.stp.StpUtil;\r\n\r\nvar dataInfo = db.table(\"base_salesman\").where().eq(\"sales_id\", body.projectId).selectOne();\r\n \r\nreturn dataInfo;', NULL, NULL, NULL, NULL, '2025-02-24 11:10:14', NULL, NULL, NULL, 0, NULL, NULL, NULL);
