INSERT INTO `magic_api_file` VALUES ('/dev-api/api/应用管理/合同管理/列表.ms', '{\n  \"properties\" : { },\n  \"id\" : \"442bdd73adb9494c8ab5a453f13a87c9\",\n  \"script\" : null,\n  \"groupId\" : \"4fe0b07bea84438f938f9e2ae6ca948a\",\n  \"name\" : \"列表\",\n  \"createTime\" : null,\n  \"updateTime\" : 1739256534228,\n  \"lock\" : \"0\",\n  \"createBy\" : null,\n  \"updateBy\" : null,\n  \"path\" : \"list\",\n  \"method\" : \"POST\",\n  \"parameters\" : [ ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : null,\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nimport cn.dev33.satoken.stp.StpUtil;\r\nimport magic.boot.utils.LoginHelper;\r\n\r\nlet loginUser = LoginHelper.getLoginUser();\r\nlet userId = LoginHelper.getUserId();\r\nlet isAdmin = loginUser.isAdministrator();\r\n\r\nlet result = db.page(\"\"\"\r\n    select * from base_contract \r\n    where 1=1\r\n    ?{!isAdmin, and create_by = #{userId}}\r\n    ?{body.contractCode, and contract_code like concat(\'%\',#{body.contractCode},\'%\')}\r\n    ?{body.contractName , and contract_name like concat(\'%\',#{body.contractName},\'%\')}\r\n    order by contract_id desc\r\n\"\"\");\r\nreturn result;', NULL, NULL, NULL, NULL, '2025-02-11 14:38:34', NULL, NULL, NULL, 0, NULL, NULL, NULL);
