INSERT INTO `magic_api_file` VALUES ('/dev-api/api/应用管理/页面管理/分类管理/列表.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"6d63eb2030ca456fa3aba1d976c4986a\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"2125a0c95fd0461bb41723c516b4d229\",\r\n  \"name\" : \"列表\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1712022873564,\r\n  \"lock\" : \"0\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"list\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar list = db.select(\"\"\"\r\n    select * \r\n    from lc_pages_classify\r\n    where 1 = 1\r\n    ?{name, and name = #{name}}\r\n\"\"\")\r\n\r\nif (list.length == 1) {\r\n    return list;\r\n}\r\nlist.filter(item => {\r\n    var arr = list.filter(child => item.id == child.parentId);\r\n    arr.length > 0 ? (item.children = arr) : false;\r\n    return item.parentId == \'0\';\r\n})\r\n\r\nreturn list.filter(item => item.parentId == \'0\');', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/应用管理/页面管理/分类管理/删除.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"cf71ab8e4ff848e7aefa1c6eb4644e02\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"2125a0c95fd0461bb41723c516b4d229\",\r\n  \"name\" : \"删除\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1712026703236,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"delete/{id}\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nreturn db.transaction(()=>{\r\n    var row = db.table(\"lc_pages_classify\").where().eq(\"id\", id).delete();\r\n    if(row){\r\n        // 删除子集\r\n        db.table(\"lc_pages_classify\").where().eq(\"parent_id\", id).delete();\r\n    }\r\n    return row;\r\n});', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/应用管理/页面管理/分页.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"0b62bb303bc9442f8b0a9b0757d62c8c\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"469af969df9e4fe4bf2c70a9608a517e\",\r\n  \"name\" : \"分页\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1712020970046,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"page\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar list = db.page(\"\"\"\r\n    select p.*,GROUP_CONCAT(menu_id) as menu_ids\r\n    from lc_pages p\r\n    left join lc_pages_menu m on m.pages_id = p.id\r\n    where 1 = 1\r\n    ?{status != null, and status = #{status}}\r\n    ?{parentId, and parent_id = #{parentId}}\r\n    ?{creatorId, and creator_id = #{creatorId}}\r\n    ?{title, and title = #{title}}\r\n    ?{classify, and classify = #{classify}}\r\n    GROUP BY p.id\r\n    order by update_time desc\r\n\"\"\")\r\nreturn list', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/应用管理/页面管理/删除.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"2bfd044cf07f42b4a9c1ce7402b8de4e\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"469af969df9e4fe4bf2c70a9608a517e\",\r\n  \"name\" : \"删除\",\r\n  \"createTime\" : 1688627828397,\r\n  \"updateTime\" : 1688517379847,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"delete/{id}\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar val = db.transaction(()=>{\r\n    db.table(\"lc_pages\").where().eq(\"id\", id).delete()\r\n    db.table(\"lc_pages_menu\").where().eq(\"pages_id\", id).delete()\r\n    return \"OK\"\r\n});\r\n\r\nreturn val;', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/应用管理/页面管理/批量删除.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"33fbeebccb774feaba2e5276843658e5\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"469af969df9e4fe4bf2c70a9608a517e\",\r\n  \"name\" : \"批量删除\",\r\n  \"createTime\" : 1688627828399,\r\n  \"updateTime\" : 1688517378271,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"batchDelete\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar val = db.transaction(()=>{\r\n    for(item in body.ids){\r\n        db.table(\"lc_pages\").where().eq(\"id\", item).delete()\r\n        db.table(\"lc_pages_menu\").where().eq(\"pages_id\", item).delete()\r\n    }\r\n    return \"OK\"\r\n});\r\n\r\nreturn val;', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/应用管理/页面管理/根据ID获取页面信息.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"c39d0fa055c848a4b073f604e9cac7b7\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"469af969df9e4fe4bf2c70a9608a517e\",\r\n  \"name\" : \"根据ID获取页面信息\",\r\n  \"createTime\" : 1688627828402,\r\n  \"updateTime\" : 1688517376767,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"get/{id}\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nreturn db.table(\"lc_pages\").where().eq(\"id\",id).selectOne()', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/应用管理/页面管理/根据菜单ID获取页面信息.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"ab48add7e308465fb5a77d7cb4c52218\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"469af969df9e4fe4bf2c70a9608a517e\",\r\n  \"name\" : \"根据菜单ID获取页面信息\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1688697302675,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"pagesInfo/{menuId}\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar info = db.selectOne(\"\"\"select * from lc_pages_menu where menu_id = #{menuId}\"\"\")\r\nif(info == null){\r\n     exit 500, \'该菜单未绑定页面!\'\r\n}\r\n\r\nreturn db.table(\"lc_pages\").where().eq(\"id\",info.pagesId).selectOne()', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/应用管理/页面管理/绑定菜单.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"6e26766b5468454ea95c2d856d8fb45f\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"469af969df9e4fe4bf2c70a9608a517e\",\r\n  \"name\" : \"绑定菜单\",\r\n  \"createTime\" : 1688627828409,\r\n  \"updateTime\" : 1688517366542,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"bindMenu\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar val = db.transaction(()=>{\r\n    db.table(\"lc_pages_menu\").where().eq(\"pages_id\", body.id).delete()\r\n    if(body.menuIds){\r\n        for(item in body.menuIds){\r\n            db.table(\"lc_pages_menu\").where().eq(\"menu_id\", item).delete()\r\n            db.insert(\"\"\"insert into lc_pages_menu(pages_id,menu_id)values(#{body.id},#{item})\"\"\")\r\n        }\r\n    }\r\n    return \"OK\"\r\n});\r\n\r\nreturn val;', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
