INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统监控/在线用户.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"b2cd6dc8ddc84ec6bb3b66b9ee4ebee3\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"da560e6b25b844519c3ac1c34112e298\",\r\n  \"name\" : \"在线用户\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1708933795963,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"onlineUser\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport cn.dev33.satoken.stp.StpUtil;\r\nimport log;\r\n\r\nvar tokens = StpUtil.searchTokenValue(\"\", 0, -1, true).map(item => {return item.substring(item.lastIndexOf(\':\')+1,item.length())});\r\nlog.info(\"{}\",tokens)\r\nreturn db.page(\"\"\"\r\n    select * from sys_login_log\r\n    where token in (#{tokens})\r\n    ?{username, and username like concat(\'%\', #{username}, \'%\')}\r\n    ?{ip, and ip like concat(\'%\', #{ip}, \'%\')}\r\n    order by create_time desc\r\n\"\"\")', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
