INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/字典管理/保存.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"fd2d0d2447754c18ba57c68e8402647c\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"79b4851948504948ad76ca5310c94bfd\",\r\n  \"name\" : \"保存\",\r\n  \"createTime\" : 1688627065458,\r\n  \"updateTime\" : 1688517335971,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"save\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nreturn db.insert(\"\"\"\r\n    INSERT INTO sys_dict(`id`, `parent_id`, `group_name`, `type`, `dic_value`, `dic_label`, `sort`, `text1`, `text2`, `text3`, `update_time`, `create_time`, `remarks`) \r\n    VALUES \r\n    (uuid(), #{body.parentId},#{body.groupName},#{body.type},#{body.dicValue},#{body.dicLabel},#{body.sort},#{body.text1},#{body.text2},#{body.text3},now(),now(),#{body.remarks})\r\n\"\"\")', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/字典管理/修改.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"35c262b4bd4e4cd29c3f852e5d487cbd\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"79b4851948504948ad76ca5310c94bfd\",\r\n  \"name\" : \"修改\",\r\n  \"createTime\" : 1688627065461,\r\n  \"updateTime\" : 1688517341169,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"update\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nreturn db.update(\"\"\"\r\n    update sys_dict set \r\n    update_time = now()\r\n    ?{body.parentId, ,`parent_id` = #{body.parentId}}\r\n    ?{body.groupNme, ,`group_name` = #{body.groupName}}\r\n    ?{body.type, ,`type` = #{body.type}}\r\n    ?{body.dicValue, ,`dic_value` = #{body.dicValue}}\r\n    ?{body.dicLabel, ,`dic_label` = #{body.dicLabel}}\r\n    ?{body.sort, ,`sort` = #{body.sort}}\r\n    ?{body.text1, ,`text1` = #{body.text1}}\r\n    ?{body.text2, ,`text2` = #{body.text2}}\r\n    ?{body.text3, ,`text3` = #{body.text3}}\r\n    ?{body.remarks, ,`remarks` = #{body.remarks}}\r\n    where id = #{body.id}\r\n\"\"\")', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/字典管理/列表.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"42c28b72bc3e4560b407282a40737ba9\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"79b4851948504948ad76ca5310c94bfd\",\r\n  \"name\" : \"列表\",\r\n  \"createTime\" : 1688627065464,\r\n  \"updateTime\" : 1688517337704,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"list\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nreturn db.select(\"\"\"\r\n    select d.* \r\n    from sys_dict d\r\n    where 1 = 1\r\n    ?{parentId, and parent_id = #{parentId}}\r\n    ?{groupName, and group_name = #{groupName}}\r\n    ?{dicValue, and dic_value = #{dicValue}}\r\n    order by sort\r\n\"\"\")', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/字典管理/删除.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"4c658ae507574ce9a0503ac8fea346ae\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"79b4851948504948ad76ca5310c94bfd\",\r\n  \"name\" : \"删除\",\r\n  \"createTime\" : 1688627065467,\r\n  \"updateTime\" : 1688517339291,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"delete/{id}\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar val = db.transaction(()=>{\r\n    var list = db.select(\"\"\"\r\n        with recursive t as (	\r\n            select id from sys_dict where id = #{id}\r\n            union all\r\n            select a.id from sys_dict a \r\n            join t on a.parent_id = t.id\r\n        )\r\n        select id from t\r\n    \"\"\")\r\n\r\n    for(item in list){\r\n        db.table(\"sys_dict\").where().eq(\"id\", item.id).delete()\r\n    }\r\n    return \"OK\"\r\n});\r\n\r\nreturn val;', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/字典管理/字典树.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"45ee381e52c64cc9ad8263b1dfbe6709\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"79b4851948504948ad76ca5310c94bfd\",\r\n  \"name\" : \"字典树\",\r\n  \"createTime\" : 1688627065470,\r\n  \"updateTime\" : 1688517343301,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"tree\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar list = db.select(\"\"\"\r\n    select d.* \r\n    from sys_dict d\r\n    where 1 = 1\r\n    ?{parentId, and parent_id = #{parentId}}\r\n    ?{groupName, and group_name = #{groupName}}\r\n    ?{dicValue, and dic_value = #{dicValue}}\r\n    order by sort\r\n\"\"\")\r\n\r\nif (list.length == 1) {\r\n    return list;\r\n}\r\nlist.filter(item => {\r\n    var arr = list.filter(child => item.id == child.parentId);\r\n    arr.length > 0 ? (item.children = arr) : false;\r\n    return item.parentId == 0;\r\n})\r\n\r\nreturn list.filter(item => item.parentId == 0);', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
