INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/安全/登出.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"80444160d7dd4f59991a792b1dafd4ab\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1e5946084f1b47b5aea7fb8b2829c2cd\",\r\n  \"name\" : \"登出\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1688634354515,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"logout\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport \'cn.dev33.satoken.stp.StpUtil\';\r\nStpUtil.logout();\r\nexit 200', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/安全/登录.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"60a768ae9748403dbcdf07e598511aa8\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1e5946084f1b47b5aea7fb8b2829c2cd\",\r\n  \"name\" : \"登录\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1731121093536,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"login\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ {\r\n    \"name\" : \"require_login\",\r\n    \"value\" : \"false\",\r\n    \"description\" : \"该接口需要登录才允许访问\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"requestBody\" : \"{\\r\\n    \\\"code\\\":\\\"111132\\\"\\r\\n}\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : \"{\\n    \\\"code\\\": 0,\\n    \\\"message\\\": \\\"验证码有误，请重新获取！\\\",\\n    \\\"result\\\": null\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : {\r\n    \"name\" : \"\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"Object\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : \"\",\r\n    \"error\" : \"\",\r\n    \"expression\" : \"\",\r\n    \"children\" : [ {\r\n      \"name\" : \"code\",\r\n      \"value\" : \"111132\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"String\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    } ]\r\n  },\r\n  \"responseBodyDefinition\" : {\r\n    \"name\" : \"\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"Object\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : \"\",\r\n    \"error\" : \"\",\r\n    \"expression\" : \"\",\r\n    \"children\" : [ {\r\n      \"name\" : \"code\",\r\n      \"value\" : \"500\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Integer\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"message\",\r\n      \"value\" : \"系统内部出现错误\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"String\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"result\",\r\n      \"value\" : \"null\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Object\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\nimport cn.dev33.satoken.stp.StpUtil;\r\nimport cn.hutool.http.useragent.UserAgentUtil;\r\nimport cn.hutool.http.useragent.UserAgent;\r\nimport com.tansci.utils.Sha256Util;\r\nimport com.tansci.utils.SystemUtils;\r\nimport com.tansci.model.CodeCacheMap;\r\nimport request;\r\n\r\nUserAgent ua = UserAgentUtil.parse(request.getHeaders(\"User-Agent\")[0])\r\n// 判断验证码\r\nif(!body.code || CodeCacheMap.get(body.code) != body.code){\r\n    exit 0, \'验证码有误，请重新获取！\'\r\n}\r\nCodeCacheMap.remove(body.code)\r\n\r\nvar user = db.table(\"sys_user\").where().eq(\"username\",body.username).selectOne();\r\nvar log = {\r\n    username: body.username,\r\n    type: \'成功\',\r\n    ip: request.getClientIP(),\r\n    browser: ua.getBrowser().toString(),\r\n    os: ua.getOs().toString(),\r\n    address: SystemUtils.getAddress(request.getClientIP()),\r\n    message: \'成功\'\r\n}\r\n\r\nif(!user || user.password != Sha256Util.getSHA256(body.password)){\r\n    log.failPassword = body.password\r\n    log.type = \'失败\'\r\n    log.message = \'用户名或密码错误\'\r\n    db.insert(\"\"\"\r\n        insert into sys_login_log(id,username,fail_password,type,browser,os,address,ip,message,create_time) values \r\n        (uuid(),#{log.username},#{log.failPassword},#{log.type},#{log.browser},#{log.os},#{log.address},#{log.ip},#{log.message},now())\r\n    \"\"\")    \r\n    exit 0,\'用户名或密码错误!\'\r\n}\r\n\r\nif(user.isLogin == 1){\r\n    log.type = \"失败\"\r\n    log.message = \"该账号已被禁用\"\r\n    db.insert(\"\"\"\r\n        insert into sys_login_log(id,username,fail_password,type,browser,os,address,ip,message,create_time) values \r\n        (uuid(),#{log.username},#{log.failPassword},#{log.type},#{log.browser},#{log.os},#{log.address},#{log.ip},#{log.message},now())\r\n    \"\"\")\r\n    exit 0,\'该账号已被禁用!\'\r\n}\r\n\r\nStpUtil.login(user.id)\r\nvar token = StpUtil.getTokenValueByLoginId(user.id)\r\nlog.token = token\r\ndb.insert(\"\"\"\r\n    insert into sys_login_log(id,username,fail_password,type,browser,os,address,ip,token,message,create_time) values \r\n    (uuid(),#{log.username},#{log.failPassword},#{log.type},#{log.browser},#{log.os},#{log.address},#{log.ip},#{log.token},#{log.message},now())\r\n\"\"\")\r\nreturn StpUtil.getTokenValueByLoginId(user.id)', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/安全/获取当前用户权限.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"7a1ae4380b62499b83b68312f821e8ef\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1e5946084f1b47b5aea7fb8b2829c2cd\",\r\n  \"name\" : \"获取当前用户权限\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1688712188050,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"permissions\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : null,\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport \'cn.dev33.satoken.stp.StpUtil\';\r\n\r\nvar userId = StpUtil.getLoginId()\r\nreturn db.select(\"\"\"\r\n    select DISTINCT m.permission \r\n    from sys_menu m\r\n    left join sys_role_menu rm on rm.menu_id = m.id\r\n    left join sys_user_role ur on ur.role_id = rm.role_id \r\n    where m.is_del = 0\r\n    and m.permission != \'\'\r\n    and m.permission IS NOT NULL\r\n    ?{userId && userId != \'1\', and ur.user_id = #{userId}}\r\n\"\"\").map((it) => {return it.permission})', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/安全/获取验证码.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"f1a4ad9f555c43d487773c175fbe5b9f\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1e5946084f1b47b5aea7fb8b2829c2cd\",\r\n  \"name\" : \"获取验证码\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1708928493064,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"code\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ {\r\n    \"name\" : \"require_login\",\r\n    \"value\" : \"false\",\r\n    \"description\" : \"该接口需要登录才允许访问\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : \"{\\n    \\\"code\\\": 500,\\n    \\\"message\\\": \\\"系统内部出现错误\\\",\\n    \\\"result\\\": null\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\n// 纯数字\r\nimport cn.hutool.captcha.CaptchaUtil;\r\nimport cn.hutool.captcha.LineCaptcha;\r\nimport cn.hutool.captcha.generator.RandomGenerator;\r\nimport java.io.ByteArrayOutputStream;\r\nimport java.io.OutputStream;\r\nimport com.tansci.model.CodeCacheMap;\r\n\r\nvar lineCaptcha = CaptchaUtil.createLineCaptcha(100, 60);\r\nlineCaptcha.setGenerator(new RandomGenerator(\"0123456789\", 4));\r\nCodeCacheMap.put(lineCaptcha.getCode(),lineCaptcha.getCode())\r\n\r\nOutputStream bOut = new ByteArrayOutputStream();\r\nlineCaptcha.write(bOut)\r\nreturn bOut.toByteArray()\r\n\r\n// 数字字母组合\r\n// import cn.hutool.captcha.CaptchaUtil;\r\n// import cn.hutool.captcha.LineCaptcha;\r\n// import java.io.ByteArrayOutputStream;\r\n// import java.io.OutputStream;\r\n// import com.tansci.model.CodeCacheMap;\r\n\r\n// var lineCaptcha = CaptchaUtil.createLineCaptcha(100, 60);\r\n// CodeCacheMap.put(lineCaptcha.getCode(),lineCaptcha.getCode())\r\n\r\n// OutputStream bOut = new ByteArrayOutputStream();\r\n// lineCaptcha.write(bOut)\r\n// return bOut.toByteArray()', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
