INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/用户管理/group.json', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"fc83134da85f4beaa18511d00d4ff661\",\r\n  \"name\" : \"用户管理\",\r\n  \"type\" : \"api\",\r\n  \"parentId\" : \"acff5ad7aae64de2acb03e1d16a58ce2\",\r\n  \"path\" : \"user\",\r\n  \"createTime\" : 1688627065423,\r\n  \"updateTime\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"paths\" : [ ],\r\n  \"options\" : [ ]\r\n}', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/用户管理/保存.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"6bdc64e2ac314291a4c6ee857edeb458\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"fc83134da85f4beaa18511d00d4ff661\",\r\n  \"name\" : \"保存\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1708659604274,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"save\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport com.tansci.utils.Sha256Util;\r\n\r\nvar count = db.selectInt(\"\"\"select count(*) from sys_user where username = #{body.username}\"\"\")\r\nif(count > 0){\r\n    exit 500, \'用户名称已存在！\'\r\n}\r\n\r\nvar id = uuid();\r\nvar password = Sha256Util.getSHA256(body.password);\r\nvar row = db.insert(\"\"\"\r\n    INSERT INTO sys_user(`id`, `username`, `password`, `nickname`, `type`, `phone`,`avatar`,`gender`,`birthday`,`address`,`email`, `is_del`, `update_time`, `create_time`, `remarks`) \r\n    VALUES \r\n    (#{id}, #{body.username},#{password},#{body.nickname},#{body.type},#{body.phone},#{body.avatar},#{body.gender},#{body.birthday},#{body.address},#{body.email},0,now(),now(),#{body.remarks})\r\n\"\"\")\r\n\r\ndb.insert(\"\"\"insert into sys_user_role(user_id,role_id)values(#{id},#{body.roleId})\"\"\")\r\n\r\nreturn row', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/用户管理/修改.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"064dd0495efd4c3999e3236cd8f1f94b\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"fc83134da85f4beaa18511d00d4ff661\",\r\n  \"name\" : \"修改\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1688699586759,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"update\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar row = db.update(\"\"\"\r\n    update sys_user set \r\n    update_time = now()\r\n    ?{body.nickname, ,`nickname` = #{body.nickname}}\r\n    ?{body.type, ,`type` = #{body.type}}\r\n    ?{body.phone, ,`phone` = #{body.phone}}\r\n    ?{body.avatar, ,`avatar` = #{body.avatar}}\r\n    ?{body.gender, ,`gender` = #{body.gender}}\r\n    ?{body.birthday, ,`birthday` = #{body.birthday}}\r\n    ?{body.address, ,`address` = #{body.address}}\r\n    ?{body.email, ,`email` = #{body.email}}\r\n    ?{body.isDel != null, ,`is_del` = #{body.isDel}}\r\n    ?{body.isLogin != null, ,`is_login` = #{body.isLogin}}\r\n    ?{body.remarks, ,`remarks` = #{body.remarks}}\r\n    where id = #{body.id}\r\n\"\"\")\r\n\r\nif(body.roleId != null){\r\n    db.update(\"\"\"update sys_user_role set role_id = #{body.roleId} where user_id = #{body.id}\"\"\")\r\n}\r\n\r\nreturn row;', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/用户管理/分页.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"396c586ab1a74de6aad78a0549d57952\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"fc83134da85f4beaa18511d00d4ff661\",\r\n  \"name\" : \"分页\",\r\n  \"createTime\" : 1688627065485,\r\n  \"updateTime\" : 1688517327728,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"page\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nreturn db.page(\"\"\"\r\n    select u.*,ur.role_id\r\n    from sys_user u\r\n    left join sys_user_role ur on ur.user_id = u.id\r\n    where is_del = 0\r\n    ?{username , and username = #{username}}\r\n    ?{status != null , and status = #{status}}\r\n    ?{phone , and phone = #{phone}}\r\n    ?{name , and name like concat(\'%\',#{name},\'%\')}\r\n    order by update_time desc \r\n\"\"\")', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/用户管理/列表.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"b2c3b55a5a2e4a23bfc7af17e6143b8f\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"fc83134da85f4beaa18511d00d4ff661\",\r\n  \"name\" : \"列表\",\r\n  \"createTime\" : 1688627065488,\r\n  \"updateTime\" : 1688690611112,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"list\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nreturn db.select(\"\"\"\r\n    select * from sys_user\r\n    where is_del = 0\r\n    ?{username , and username = #{username}}\r\n    ?{status != null , and status = #{status}}\r\n    ?{phone , and phone = #{phone}}\r\n    ?{name , and name like concat(\'%\',#{name},\'%\')}\r\n    order by update_time desc \r\n\"\"\")', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/用户管理/删除.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"8370e79fd2694d5f86085f0bd7a0efe8\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"fc83134da85f4beaa18511d00d4ff661\",\r\n  \"name\" : \"删除\",\r\n  \"createTime\" : 1688627065491,\r\n  \"updateTime\" : 1688517330950,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"delete/{id}\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar val = db.transaction(()=>{\r\n    db.table(\"sys_user\").where().eq(\"id\", id).delete()\r\n    db.table(\"sys_user_role\").where().eq(\"user_id\", id).delete()\r\n    return \"OK\"\r\n});\r\n\r\nreturn val;', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/用户管理/详情.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"01cc62375d6c4a86b050d64e60cf5872\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"fc83134da85f4beaa18511d00d4ff661\",\r\n  \"name\" : \"详情\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1731053828242,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"info\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport cn.dev33.satoken.stp.StpUtil;\r\n\r\nvar userId = StpUtil.getLoginId();\r\nvar user = db.table(\"sys_user\").where().eq(\"id\", userId).selectOne();\r\nuser.authorities = db.select(\"\"\"\r\n    select DISTINCT m.permission \r\n    from sys_menu m\r\n    left join sys_role_menu rm on rm.menu_id = m.id\r\n    left join sys_user_role ur on ur.role_id = rm.role_id \r\n    where m.is_del = 0\r\n    and m.permission != \'\'\r\n    and m.permission IS NOT NULL\r\n    ?{userId && userId != \'1\', and ur.user_id = #{userId}}\r\n\"\"\").map((it) => {return it.permission})\r\nreturn user;', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
