INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/菜单管理/删除.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"26ff3d166de34575a3bf6d41465c80e7\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"67b2ce258e24491194b74992958c74aa\",\r\n  \"name\" : \"删除\",\r\n  \"createTime\" : 1688627065524,\r\n  \"updateTime\" : 1688517304774,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"delete/{id}\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar val = db.transaction(()=>{\r\n    var list = db.select(\"\"\"\r\n        with recursive t as (	\r\n            select id from sys_menu where id = #{id}\r\n            union all\r\n            select a.id from sys_menu a \r\n            join t on a.parent_id = t.id\r\n        )\r\n        select id from t\r\n    \"\"\")\r\n\r\n    for(item in list){\r\n        db.table(\"sys_menu\").where().eq(\"id\", item.id).delete()\r\n        db.table(\"sys_role_menu\").where().eq(\"menu_id\", item.id)\r\n    }\r\n    return \"OK\"\r\n});\r\n\r\nreturn val;', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/菜单管理/菜单树.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"f90132707c3e401c926eaf2ada6ec81a\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"67b2ce258e24491194b74992958c74aa\",\r\n  \"name\" : \"菜单树\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1688721005404,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"tree\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport \'cn.dev33.satoken.stp.StpUtil\';\r\n\r\nvar userId = StpUtil.getLoginId();\r\n\r\nvar menus = db.select(\"\"\"\r\n    select m.* \r\n    from sys_menu m\r\n    where m.is_del = 0\r\n    ?{isShow  != null, and m.is_show = #{isShow}}\r\n    ?{userId && userId != 1, and m.id in (\r\n        select rm.menu_id \r\n        from sys_role_menu rm\r\n        left join sys_user_role ur on ur.role_id = rm.role_id\r\n        where ur.user_id = #{userId})\r\n    }\r\n    order by sort asc\r\n\"\"\")\r\n\r\nif (menus.length == 1) {\r\n    return menus;\r\n}\r\nmenus.filter(item => {\r\n    var arr = menus.filter(child => item.id == child.parentId);\r\n    arr.length > 0 ? (item.children = arr) : false;\r\n    return item.parentId == 0;\r\n})\r\n\r\nreturn menus.filter(item => item.parentId == 0);', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/菜单管理/菜单路由.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"62020bd7a49949378e90ce2d14fef8f7\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"67b2ce258e24491194b74992958c74aa\",\r\n  \"name\" : \"菜单路由\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1689229170425,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"menus\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport \'cn.dev33.satoken.stp.StpUtil\';\r\n\r\nvar userId = StpUtil.getLoginId();\r\n\r\nvar list = db.select(\"\"\"\r\n    select m.* \r\n    from sys_menu m\r\n    where m.is_del = 0\r\n    and m.is_show = 1\r\n    ?{userId && userId != 1, and m.id in (\r\n        select rm.menu_id \r\n        from sys_role_menu rm\r\n        left join sys_user_role ur on ur.role_id = rm.role_id\r\n        where ur.user_id = #{userId})\r\n    }\r\n    order by sort asc\r\n\"\"\")\r\n\r\nvar menus = []\r\nlist.each(item => {\r\n    menus.push({\r\n        id: item.id,\r\n        parentId: item.parentId,\r\n        path: item.url,\r\n        name: item.name,\r\n        icon: item.icon,\r\n        sort: item.sort,\r\n        component: item.component == null || item.component == \'\' ? \"Layout\" : item.component,\r\n        componentType: item.componentType,\r\n        isShow: item.isShow,\r\n        meta: {\r\n            title: item.chineseName,\r\n            keepAlive: item.keepAlive,\r\n            isShow: item.isShow,\r\n            id: item.id,\r\n            openMode: item.openMode,\r\n            type: item.componentType,\r\n        }\r\n    })\r\n})\r\n\r\nif (menus.length == 1) {\r\n    return menus;\r\n}\r\nmenus.filter(item => {\r\n    var arr = menus.filter(child => item.id == child.parentId);\r\n    arr.length > 0 ? (item.children = arr) : false;\r\n    return item.parentId == 0;\r\n})\r\n\r\nvar _menus = menus.filter(item => item.parentId == 0);\r\n_menus.each(item=>{\r\n    if(!item.children){\r\n        item.children = [{\r\n            id: item.id,\r\n            parentId: item.parentId,\r\n            path: item.path,\r\n            name: item.name,\r\n            icon: item.icon,\r\n            sort: item.sort,\r\n            component: item.component,\r\n            componentType: item.componentType,\r\n            isShow: item.isShow,\r\n            meta: item.meta\r\n        }]\r\n        item.componentType = 0;\r\n    }\r\n})\r\n\r\n\r\nreturn _menus;', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
