INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/角色管理/保存.ms', '{\n  \"properties\" : { },\n  \"id\" : \"963fbdab7f1e4c5482d94467994e076b\",\n  \"script\" : null,\n  \"groupId\" : \"e3e7b79651ef4023bf808869bda70162\",\n  \"name\" : \"保存\",\n  \"createTime\" : null,\n  \"updateTime\" : 1736931081061,\n  \"lock\" : \"0\",\n  \"createBy\" : null,\n  \"updateBy\" : null,\n  \"path\" : \"save\",\n  \"method\" : \"POST\",\n  \"parameters\" : [ ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : \"{\\n    \\\"code\\\": 402,\\n    \\\"message\\\": \\\"用户凭证已过期，请重新登录！\\\",\\n    \\\"data\\\": \\\"未能读取到有效 token\\\"\\n}\",\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nvar code = uuid().substring(0,10)\r\nreturn db.insert(\"\"\"\r\n    INSERT INTO sys_role(`id`, `name`, `code`, `permission`, `sort`, `is_del`, `creator`, `update_time`, `create_time`, `remarks`) \r\n    VALUES \r\n    (uuid(), #{body.name},#{code},#{body.permission},#{body.sort},0,#{body.creator},now(),now(),#{body.remarks})\r\n\"\"\")', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/角色管理/修改.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"62c0822e34124adcb52c79d9f2e128f3\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"e3e7b79651ef4023bf808869bda70162\",\r\n  \"name\" : \"修改\",\r\n  \"createTime\" : 1688627065559,\r\n  \"updateTime\" : 1688517323756,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"update\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nreturn db.update(\"\"\"\r\n    update sys_role set \r\n    update_time = now()\r\n    ?{body.name, ,`name` = #{body.name}}\r\n    ?{body.code, ,`code` = #{body.code}}\r\n    ?{body.sort, ,`sort` = #{body.sort}}\r\n    ?{body.is_del, ,`is_del` = #{body.is_del}}\r\n    ?{body.permission, ,`permission` = #{body.permission}}\r\n    ?{body.remarks, ,`remarks` = #{body.remarks}}\r\n    where id = #{body.id}\r\n\"\"\")', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/角色管理/分页.ms', '{\n  \"properties\" : { },\n  \"id\" : \"d8a1114e2da54d7c857d4c54d5bc5880\",\n  \"script\" : null,\n  \"groupId\" : \"e3e7b79651ef4023bf808869bda70162\",\n  \"name\" : \"分页\",\n  \"createTime\" : 1688627065564,\n  \"updateTime\" : 1736495563929,\n  \"lock\" : \"1\",\n  \"createBy\" : null,\n  \"updateBy\" : null,\n  \"path\" : \"page\",\n  \"method\" : \"GET\",\n  \"parameters\" : [ ],\n  \"options\" : [ ],\n  \"requestBody\" : \"\",\n  \"headers\" : [ ],\n  \"paths\" : [ ],\n  \"responseBody\" : null,\n  \"description\" : null,\n  \"requestBodyDefinition\" : null,\n  \"responseBodyDefinition\" : null\n}\r\n================================\r\nreturn db.page(\"\"\"\r\n    select * from sys_role\r\n    where is_del = 0\r\n    ?{code , and code = #{code}}\r\n    ?{name , and name like concat(\'%\',#{name},\'%\')}\r\n    order by sort \r\n\"\"\")', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/角色管理/列表.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"71851668125c451f9e322f0c5f7828a8\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"e3e7b79651ef4023bf808869bda70162\",\r\n  \"name\" : \"列表\",\r\n  \"createTime\" : 1688627065570,\r\n  \"updateTime\" : 1688517320177,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"list\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nreturn db.select(\"\"\"\r\n    select * from sys_role\r\n    where is_del = 0\r\n    ?{code , and code = #{code}}\r\n    ?{name , and name like concat(\'%\',#{name},\'%\')}\r\n    order by sort \r\n\"\"\")', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/角色管理/删除.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"f3450863db7c4600b8fb199e5c07eaec\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"e3e7b79651ef4023bf808869bda70162\",\r\n  \"name\" : \"删除\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1688698546137,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"delete/{id}\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar val = db.transaction(()=>{\r\n    db.table(\"sys_role\").where().eq(\"id\", id).delete()\r\n    db.table(\"sys_role_menu\").where().eq(\"role_id\", id).delete()\r\n    db.table(\"sys_user_role\").where().eq(\"role_id\", id).delete()\r\n    db.table(\"sys_user_org\").where().eq(\"role_id\", id).delete()\r\n    return \"OK\"\r\n});\r\n\r\nreturn val;', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/角色管理/数据权限.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"06ca5c4e8ce04fbc85bece6274208bec\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"e3e7b79651ef4023bf808869bda70162\",\r\n  \"name\" : \"数据权限\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1688698471253,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"dataPermissions\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar val = db.transaction(()=>{\r\n    db.table(\"sys_role_org\").where().eq(\"role_id\", body.id).delete()\r\n\r\n    for(item in body.orgIds){\r\n        db.insert(\"\"\"INSERT INTO sys_role_org (role_id,org_id) VALUES (#{body.id}, #{item})\"\"\")\r\n    }\r\n\r\n    return \"OK\"\r\n});\r\n\r\nreturn val;', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/角色管理/获取权限组织.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"9ea9a1c0a8a24a6e9e9b584c87d94a28\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"e3e7b79651ef4023bf808869bda70162\",\r\n  \"name\" : \"获取权限组织\",\r\n  \"createTime\" : null,\r\n  \"updateTime\" : 1688698474013,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"orgList/{id}\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport \'@get:/system/org/list\' as getOrg;\r\n\r\nvar list = db.select(\"\"\"select * from sys_role_org where role_id = #{id}\"\"\");\r\nvar selected = list.map((item) =>{\r\n    return item.orgId\r\n})\r\nreturn {\r\n    list: getOrg(),\r\n    selected: selected\r\n}', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/角色管理/获取权限菜单.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"95c1495b484e4f06ab5f1399e45fb643\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"e3e7b79651ef4023bf808869bda70162\",\r\n  \"name\" : \"获取权限菜单\",\r\n  \"createTime\" : 1688627065578,\r\n  \"updateTime\" : 1688517318645,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"menuList/{id}\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport \'@get:/system/menu/tree\' as getTree;\r\n\r\nvar list = db.select(\"\"\"select * from sys_role_menu where role_id = #{id}\"\"\");\r\n\r\nvar ids = list.map((item) =>{\r\n    return item.menuId\r\n})\r\n\r\nreturn {\r\n    list: getTree(),\r\n    selected: ids\r\n}', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO `magic_api_file` VALUES ('/dev-api/api/系统管理/角色管理/菜单权限.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"e6b1376d15e44edea70becac58caeb35\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"e3e7b79651ef4023bf808869bda70162\",\r\n  \"name\" : \"菜单权限\",\r\n  \"createTime\" : 1688627065583,\r\n  \"updateTime\" : 1688517315336,\r\n  \"lock\" : \"1\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : \"admin\",\r\n  \"path\" : \"menuPermissions\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar val = db.transaction(()=>{\r\n    db.table(\"sys_role_menu\").where().eq(\"role_id\", body.id).delete()\r\n\r\n    for(item in body.menuIds){\r\n        db.insert(\"\"\"INSERT INTO sys_role_menu (role_id,menu_id) VALUES (#{body.id}, #{item})\"\"\")\r\n    }\r\n\r\n    return \"OK\"\r\n});\r\n\r\nreturn val;', NULL, NULL, NULL, NULL, '2024-11-10 11:14:55', NULL, NULL, NULL, 0, NULL, NULL, NULL);
