INSERT INTO `magic_script` VALUES (4, 'demo', 's4', '脚本4', 'import cn.hutool.core.collection.ListUtil;\r\n            import com.yomahub.liteflow.script.body.CommonScriptBody;\r\n            import com.yomahub.liteflow.slot.DefaultContext;\r\n            import com.yomahub.liteflow.spi.holder.ContextAwareHolder;\r\n            import com.example.liteflow.mysql.vo.Person;\r\n            import com.yomahub.liteflow.script.ScriptExecuteWrap;\r\n            import java.util.List;\r\n            import java.util.function.ToIntFunction;\r\n\r\n            public class Demo implements CommonScriptBody {\r\n                public Void body(ScriptExecuteWrap wrap) {\r\n                    DefaultContext ctx = wrap.getCmp().getFirstContextBean();\r\n                    List<Person> personList = ListUtil.toList(\r\n                            new Person(\"jack\", 15000),\r\n                            new Person(\"tom\", 23500),\r\n                            new Person(\"peter\", 18500)\r\n                    );\r\n\r\n                    int totalSalary = personList.stream().mapToInt(Person::getSalary).sum();\r\n\r\n                    System.out.println(totalSalary);\r\n                    ctx.setData(\"salary\", totalSalary);\r\n\r\n                    return null;\r\n                }\r\n            }', 'script', 'java', 1, NULL, NULL, '2024-11-26 12:17:07', NULL, NULL, 0, NULL, NULL, NULL, '000000', NULL);
INSERT INTO `magic_script` VALUES (5, 'demo', 'js1', '脚本js1', 'import com.yomahub.liteflow.script.body.CommonScriptBody;\r\nimport com.yomahub.liteflow.slot.DefaultContext;\r\nimport com.yomahub.liteflow.spi.holder.ContextAwareHolder;\r\nimport com.yomahub.liteflow.script.ScriptExecuteWrap;\r\nimport java.util.List;\r\nimport java.util.function.ToIntFunction;\r\nimport java.util.HashMap;\r\nimport java.util.List;\r\nimport java.util.Map;\r\n\r\npublic class Demo implements CommonScriptBody {\r\n	public Void body(ScriptExecuteWrap wrap) {\r\n		int v1 = 2;\r\n		int v2 = 3;\r\n		DefaultContext ctx = wrap.getCmp().getFirstContextBean();\r\n		ctx.setData(\"s1\", v1 * v2);\r\n\r\n		int totalSalary = 255;\r\n\r\n		System.out.println(totalSalary);\r\n		ctx.setData(\"salary\", 47100);\r\n\r\n		List<Map<String, Object>> dataList = ctx.getData(\"dataList\");\r\n		Map<String, Object> map = new HashMap<>();\r\n		map.put(\"a1\", 1);\r\n		map.put(\"a2\", 2);\r\n		map.put(\"a3\", 3);\r\n		dataList.add(map);\r\n\r\n		return null;\r\n	}\r\n}', 'script', 'java', 1, NULL, NULL, '2024-11-26 12:17:07', NULL, NULL, 0, NULL, NULL, NULL, '000000', NULL);
