INSERT INTO `sys_code_regular` VALUES (1, 43, 1762, '供应商信息', 'PV[yyyy][5]', 'SELECT provider_code FROM base_provider \nWhere tenant_id=\'{tenant_id}\' AND provider_code  Like \'PV%\'\nORDER BY provider_code DESC LIMIT 1;', 1, 0, '000000', NULL, NULL, '2012-06-20 15:39:18', NULL, '超级管理员', '2019-12-04 22:26:48', NULL, '超级管理员', 0, NULL, NULL, NULL);
INSERT INTO `sys_code_regular` VALUES (6, 43, 1758, '商品基础信息', 'PI[4]', 'SELECT product_code  FROM  base_product WHERE tenant_id=\'{tenant_id}\' And product_code LIKE \'PI%\' ORDER BY product_code DESC LIMIT 1;', 1, 0, '000000', NULL, NULL, '2012-06-20 16:32:31', NULL, '超级管理员', '2025-04-29 09:35:16', 1, '超级管理员', 0, NULL, NULL, NULL);
INSERT INTO `sys_code_regular` VALUES (7, 43, 232, '快递管理', 'KD[yyyy][4]', 'SELECT ExpressCorpCode @lastCode FROM Base_ExpressCorp\nWhere tenant_id=\'{tenant_id}\'\nORDER BY ExpressCorp_Id DESC LIMIT 1;', 1, 0, '000000', NULL, NULL, '2012-06-20 17:26:41', NULL, '超级管理员', '2019-12-04 22:27:06', NULL, '超级管理员', 0, NULL, NULL, NULL);
INSERT INTO `sys_code_regular` VALUES (8, 46, 1001, '预到货单', 'PO[yyyy][MM][dd][3]', 'SELECT order_code FROM in_order WHERE tenant_id=\'{tenant_id}\' AND (create_time>=\'{date}\' And create_time<=\'{date} 23:59:59\') ORDER BY order_id DESC LIMIT 1', 1, 0, '000000', NULL, NULL, '2012-06-21 15:23:05', NULL, '超级管理员', '2023-10-26 15:09:31', 1, '超级管理员', 0, NULL, NULL, NULL);
INSERT INTO `sys_code_regular` VALUES (9, 46, 1650, '入库记录单', 'PS[yyyy][MM][dd][3]', 'SELECT enter_code FROM in_enter WHERE tenant_id=\'{tenant_id}\' AND (create_time >= \'{date}\' And create_time <= \'{date} 23:59:59\') and tenant_id=\'{tenant_id}\' Order BY enter_id DESC LIMIT 1;', 1, 0, '000000', NULL, NULL, '2012-06-21 15:24:33', NULL, '超级管理员', '2023-10-26 16:18:20', 1, '超级管理员', 0, NULL, NULL, NULL);
INSERT INTO `sys_code_regular` VALUES (10, 46, 1661, '收货退货单', 'AB[yyyy][MM][dd][3]', 'SELECT return_code FROM in_return WHERE tenant_id=\'{tenant_id}\' AND (create_time>=\'{date}\' And create_time<=\'{date} 23:59:59\') ORDER BY return_id DESC LIMIT 1', 1, 0, '000000', NULL, NULL, '2012-06-21 15:25:41', NULL, '超级管理员', '2022-12-10 20:53:53', NULL, '超级管理员', 0, NULL, NULL, NULL);
INSERT INTO `sys_code_regular` VALUES (11, 46, 105, '收货换货单', 'RB[yyyy][MM][dd][3]', 'SELECT  ExchangeCode INTO @LastCode FROM purchase_exchange WHERE tenant_id=\'{tenant_id}\' AND (create_time>=\'{date}\' And create_time<=\'{date} 23:59:59\') And ExchangeCode <>\'\' And UserProduct_Id= {UserProduct_Id} ORDER BY Exchange_Id DESC LIMIT 1;', 1, 0, '000000', NULL, NULL, '2012-06-21 15:26:23', NULL, '超级管理员', '2022-12-10 20:54:08', NULL, '超级管理员', 0, NULL, NULL, NULL);
